  function fhLS(k, dflt) { try { var v = JSON.parse(localStorage.getItem(k) || 'null'); return v == null ? dflt : v; } catch (e) { return dflt; } }
  function fhLSset(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }
