    var rest = s.split(/\s*\|\s*/).map(function (seg) { FH_MEAL_RX.lastIndex = 0; var m = FH_MEAL_RX.exec(seg); return m ? seg.slice(0, m.index) : seg; }).join(' ');
    var r = fhFiberTags(rest); if (r != null) { t += r; n++; }
