    var cnt = '';
    if (vn.state === 'ok' && d) cnt = d.pending ? d.pending + ' new' : (d.total ? d.total + '' : '');
    var c = $('vn-cnt'); c.textContent = cnt; c.hidden = !cnt;
    // a note kept on this phone (not saved yet)
