      h += collCard('mtm' + i, m.title.replace(/^M\d+\.\s*/i, ''), '<span class="mtbadge ' + ms.k + '">' + esc(ms.label) + '</span>', machineBody(m, 'mtm' + i), false, 'nest mach');
