      w = w.replace(/\b(\d{1,2}|one|two|three|four|five|six|seven)\s+days?\s+ago\b/i, function (s, n) { var v = has(UNIT, String(n).toLowerCase()) ? UNIT[String(n).toLowerCase()] : +n; return fn(addDays(today, -v)); });
