          if (x === '-' && last && y && (has(UNIT, y) || has(TEN, y))) { k++; continue; }
          if (x === 'and' && (last === 'hundred' || last === 'thousand') && y && (has(UNIT, y) || has(TEN, y))) { k++; continue; }
