      var msg = 'Added ' + added.length + ' to the wish list.';
      if (skipped.length) msg += ' Already on the list: ' + skipped.map(nm).filter(Boolean).join(', ') + '.';
      wl.items = []; wl.text = ''; wl.cid = ''; wl.sig = ''; wlDraftSave();
