    lr.msg = ''; lr.base = ta.value ? ta.value.replace(/\s+$/, '') + ' ' : ''; lr.committed = ''; lr.interim = '';
    var rec; try { rec = new SR(); } catch (e) { return lrMicFail(MIC_NA); }
