    { key: 'health',   title: 'Condition & health',  fields: ['condition', 'ailments', 'medications'] },
    { key: 'goals',    title: 'Goals & history',     fields: ['goals', 'experience'] },
    { key: 'notes',    title: 'Notes',               fields: ['notes'] }
