    var max = Math.max(1, pc.pdfPages || 1);
    if (n < 1) n = 1;
    if (n > max) n = max;
    if (n === pc.page) { if (pc.focusPin && pc.fs) pcFocusPinNow(); return; }
    pcReadDomMeta();
    pc.page = n;
    pc.annotCur = '';
